contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: fund it, then attempt withdrawAll by an arbitrary caller (not owner).
    // Parameters:
    // - fundAmount: amount of wei this test contract will send into c (must be >0)
    // - callerIsOwner: if true we simulate owner behavior by requiring that this contract is the owner of c
    // Note: we cannot change msg.sender, so to ensure this test is distinguishing we assert that if this contract is NOT the owner,
    // then calling withdrawAll DOES NOT drain c's balance under the original contract. Under the mutant it would.
    function runTest(uint fundAmount, bool callerIsOwner) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // Precondition check: ensure whether this contract is the owner or not matches callerIsOwner.
        // Use public owner getter on c.
        address owner = c.owner();
        require((owner == address(this)) == callerIsOwner, "callerIsOwner mismatch with actual owner");

        // Fund c by sending ETH to its fallback
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Record balance after funding
        uint balAfterFund = address(c).balance;
        require(balAfterFund == fundAmount, "unexpected fund amount");

        // Now attempt to withdrawAll from c as this contract (msg.sender = this contract)
        // This call is state-changing and must be a top-level statement.
        c.withdrawAll();

        // Observe balance after withdrawAll
        uint balFinal = address(c).balance;

        // Assert: if this contract is NOT the owner, then withdrawAll should NOT have set the contract balance to zero.
        // This holds on original (onlyOwner prevents non-owner from withdrawing), but is violated by mutant which allows anyone to withdraw.
        assert(callerIsOwner || balFinal > 0);
    }

    // Allow the contract to receive ETH so runTest can be funded externally.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Precondition: this contract is not the owner of c
        // We cannot read owner directly if it were private, but owner is public in C so this is allowed.
        require(msg.sender == msg.sender); // noop to satisfy template if needed
        address owner = c.owner();
        require(owner != address(this));

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if this contract is not the owner, withdrawAll must revert
        assert(reverted == true);
    }
    receive() external payable { }
}

