pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: an external depositor address and an amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // restrict depositor to be non-zero and not the contract owner to emulate an EOA depositor
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));

        // bound amount to a reasonable range so vm.deal works and avoid overflow edgecases
        uint256 amt = bound(amount, 1, 1 ether);

        // Fund depositor and have them send ETH to the contract (this triggers fallback and increments depositsCount)
        vm.deal(depositor, amt);
        vm.prank(depositor);
        // send ETH to c via plain call to trigger fallback()
        (bool sent, ) = address(c).call{value: amt}("");
        require(sent);

        // sanity: contract balance should now be at least amt
        // Owner (test contract) calls withdrawAll
        // c.owner is the deployer (this test contract), so call as this contract
        // withdrawAll is public and onlyOwner; we're already the owner
        c.withdrawAll();

        // After withdrawAll on the reference contract, contract balance must be zero for any deposit scenario
        // (the mutant that calls withdraw(0) will leave balance > 0 for some inputs)
        assertTrue(address(c).balance == 0);
    }
}

