contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive calls: deposit via fallback to give contract some balance, then withdraw
    // params: depositAmount to send into c, withdrawAmount to withdraw
    function check(uint depositAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to fund deposit
        require(address(this).balance >= depositAmount, "insufficient funding for deposit");
        // send depositAmount to c to increase its balance (triggers fallback)
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "deposit failed");

        // record balances before withdraw
        uint balBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        // require we attempt a feasible withdraw
        require(withdrawAmount <= balBefore, "withdrawAmount > contract balance");

        // perform withdraw; this is the deciding call whose behavior differs between transfer (P) and send+require (M)
        c.withdraw(withdrawAmount);

        // observe balances after withdraw
        uint balAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        // General rule: call succeeds (no revert) and contract balance decreased by exactly withdrawAmount
        assert(balAfter + withdrawAmount == balBefore && selfAfter == selfBefore + withdrawAmount);
    }

    // allow this test contract to receive ETH so it can fund deposits and receive withdraws
    receive() external payable {}
}

