contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and a boolean controlling helper behaviour
    function testFuzz_property(uint256 amount, bool consumeMoreGas) public {
        // keep amount reasonable (non-zero and within balanceable range)
        vm.assume(amount > 0 && amount <= address(this).balance + 1 ether);

        // deploy helper that either uses >2300 gas in fallback (by looping) or just accepts
        Helper h = new Helper(consumeMoreGas);

        // fund this test and the contract
        vm.deal(address(this), amount + 1 ether);
        // send `amount` into c by invoking fallback (depositsCount increments but fine)
        c.sendMoney{value: 0}(address(h), 0); // no-op call to ensure c exists; ok if target is arbitrary

        // send Ether into c so it has balance to later attempt withdraws
        // we fund c by calling its fallback payable
        (bool okFund, ) = address(c).call{value: amount}("\x00");
        require(okFund);

        // call sendMoney to the helper with a small value to test behavior; the helper does nothing
        // but is used as the eventual recipient for withdraw attempts triggered by owner
        // owner is this test deployer (constructor set owner to deployer of C)
        // ensure this contract is msg.sender for owner functions
        vm.prank(address(this));
        try c.sendMoney(address(h), 0) {
            // ok
        } catch {
            // ignore
        }

        // Now the key property: the contract balance should equal the amount we deposited
        // Reference contract preserves that invariant for all inputs; the mutant can violate it
        assertTrue(address(c).balance == amount);
    }
}

// Helper: its fallback either consumes lots of gas (to cause differences when gas stipend matters)
contract Helper {
    bool public consume;
    constructor(bool _consume) payable { consume = _consume; }
    fallback() external payable {
        if (consume) {
            // burn gas beyond 2300 by doing a loop
            uint256 i = 0;
            while (i < 1000) { i++; }
        }
    }
}

