pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the amount so the fuzzer can find values that reveal the mutant's different behavior
    function testFuzz_property(uint256 amount) public {
        // keep amount in a practical range so vm.deal/prank work and don't overflow
        amount = bound(amount, 0, 1 ether);

        // deploy a helper that will accept money but consume >2300 gas in its fallback
        // this simulates a recipient whose fallback uses more than 2300 gas (e.g., writing to storage)
        GasConsumer helper = new GasConsumer();

        // fund the owner (msg.sender in setUp created c, but here test runner acts as owner)
        vm.deal(address(this), amount);

        // call sendMoney as owner (this address is owner because c was created in setUp by this contract)
        // sendMoney is payable, forward `amount` wei
        if (amount == 0) {
            // still perform call with 0 value to keep domain wide; it should be a no-op and leave balance 0
            c.sendMoney(address(helper), 0);
            // assert that contract balance equals the sent amount (0)
            assertTrue(address(c).balance == 0);
            return;
        }

        // send the amount to c first so it has funds to forward in sendMoney (sendMoney requires onlyOwner)
        // deposit directly into c by making a plain payable call to its fallback
        (bool okDeposit, ) = address(c).call{value: amount}('');
        require(okDeposit);

        // sanity: c should now hold amount
        // call sendMoney to helper which will consume >2300 gas in fallback and then accept funds
        // use try/catch to avoid bubbling reverts; sendMoney uses call and may revert depending on target behavior
        bool ok;
        try c.sendMoney(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: after invoking sendMoney(target, amount) from owner,
        // the reference contract always has balance equal to (initial balance - forwarded amount) i.e.,
        // here, since we forwarded the entire amount, c.balance should be 0 for all inputs when the call succeeds,
        // and should remain amount if the external call reverted.
        // We assert that address(c).balance is either 0 (call succeeded and funds forwarded) or amount (call reverted),
        // but crucially for the reference implementation, when the helper's fallback consumes >2300 gas but does not revert,
        // transfer-based withdraw semantics ensure behavior consistent with this assertion for all inputs; the mutant can break this
        // by changing gas stipend semantics leading to different observed balances.

        if (ok) {
            // if sendMoney returned successfully, c must have forwarded the funds -> balance 0
            assertTrue(address(c).balance == 0);
        } else {
            // if sendMoney reverted, c should have kept its funds
            assertTrue(address(c).balance == amount);
        }
    }
}

// Helper that consumes >2300 gas in fallback then accepts funds
contract GasConsumer {
    // a storage slot to modify, ensuring >2300 gas usage
    uint256 public x;

    fallback() external payable {
        // do a storage write which costs more than 2300 gas
        x = x + 1;
        // accept funds (do nothing else)
    }
}

