pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send (must be >0 and <= owner's balance) and a boolean toggle
    // We keep domain wide; amount is fuzzed. The boolean toggles which helper to deploy but is fuzzed too.
    function testFuzz_property(uint256 amount, bool useGasBurner) public {
        // Keep amount within a reasonable bound so vm.deal can fund an EOA owner
        uint256 bounded = bound(amount, 1, 1 ether);

        // owner is the test contract's default sender (deployer), which is the owner of c
        address owner = address(this);

        // fund owner so they can send bounded value
        vm.deal(owner, 1 ether);

        // pick adversarial helper: one that in fallback consumes >2300 gas then returns (succeeds)
        address helperAddr;
        if (useGasBurner) {
            // helper that burns gas (>2300) then succeeds
            helperAddr = address(new GasBurner());
        } else {
            // normal acceptor that just accepts
            helperAddr = address(new Accept());
        }

        // Owner calls sendMoney on c, forwarding bounded value
        // c.sendMoney will call helperAddr.call{value: bounded}("") from c
        vm.prank(owner);
        c.sendMoney(helperAddr, bounded);

        // After sendMoney returns, the invariant for the reference contract: c's balance equals the amount sent
        // (the reference uses transfer when withdrawing to owner elsewhere; here we assert preservation of balance
        // after a call that may consume >2300 gas in the callee. The mutant replacing transfer with send can
        // produce differing balances for some inputs because of gas forwarding differences.)
        assertTrue(address(c).balance == bounded);
    }
}

// Helper that accepts funds normally
contract Accept {
    receive() external payable {}
}

// Helper that consumes >2300 gas in fallback/receive but then succeeds
contract GasBurner {
    receive() external payable {
        // burn gas by a loop that uses more than 2300 gas
        // do some work that certainly exceeds 2300 (e.g., many SSTOREs are expensive, but we avoid SSTORE to keep minimal)
        // Use a volatile loop with assembly to burn gas
        uint256 i = 0;
        while (i < 500) {
            // do a cheap operation but enough iterations to exceed 2300
            i++;
        }
        // succeed and accept funds
    }
}

