contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller supplies: amount to fund the contract with, and a withdraw amount to attempt
    // This function will: fund c, record its balance, then attempt to call withdraw(_withdrawAmt)
    // The distinguishing property: after a non-owner calls withdraw, c's balance must remain >= its prior balance (no Ether leaves)
    function checkWithdrawCannotBeCalledByNonOwner(uint fundAmt, uint withdrawAmt) public payable {
        // ensure this test contract has enough balance to fund c
        require(address(this).balance >= fundAmt, "insufficient test balance");

        // fund c by sending Ether to its fallback
        // use call to send Ether to c (fallback is payable)
        (bool sent,) = address(c).call{value: fundAmt}("");
        require(sent, "funding failed");

        // observe balance after funding
        uint before = address(c).balance;

        // Sanity: require withdrawAmt <= before to make any change possible
        require(withdrawAmt <= before, "withdrawAmt too large");

        // Now, attempt to call withdraw as this (non-owner) contract
        // If original contract enforces onlyOwner this will revert; if mutant removed the check it will succeed and transfer
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmt));

        // observe balance after attempt
        uint after = address(c).balance;

        // The property: a non-owner's call must not decrease c's balance (on original C this holds for all inputs)
        // Expressed as: either the call reverted (ok==false) or the balance did not decrease (after >= before)
        assert(!ok || after >= before);
    }

    // allow this contract to receive Ether used for funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint amount) public payable {
        require(caller != address(0));
        // Fund the contract so there is a balance to withdraw from
        require(address(this).balance >= amount);
        // send Ether to C's fallback to increase its balance
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // Attempt to call withdraw as an arbitrary caller by using call with a constructed calldata
