            // if helper rejects (reverts on receive), sendMoney should revert and thus helper balance is still 0
            // we check that reference also leaves helper with 0 balance
            assertTrue(address(helper).balance == 0);
        }
    }
}

// Adversarial helper that either accepts or reverts on receive/fallback
contract Receiver {
    bool public accept;
    constructor(bool _accept) payable {
        accept = _accept;
    }
    fallback() external payable {
        if (!accept) revert("nope");
    }
    receive() external payable {
        if (!accept) revert("nope");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that drives C and asserts the distinguishing property
    // params:
    // - caller: the address that will call c.sendMoney (simulated by using tx.origin through low-level call)
    // - target: the target address to receive funds from c
    // - amount: amount to send from c to target
    // - fundAmount: amount to fund c first via fallback

    receive() external payable {}

    function run(address caller, address payable target, uint amount, uint fundAmount) public payable {
        // Preconditions: ensure this contract has enough balance to fund C
        require(address(this).balance >= fundAmount, "need balance to fund c");
        // fund C by calling its fallback (send ether to C)
        (bool s,) = address(c).call{value: fundAmount}("");
        require(s);

        // record c balance before the sendMoney attempt
        uint before = address(c).balance;

        // Now attempt to call sendMoney as an arbitrary caller.
        // We cannot change msg.sender of external call from within Solidity directly, so
        // we emulate a call from `caller` by using a low-level call: we craft calldata for sendMoney
        // function selector and pass it to c via call, but the msg.sender will still be this contract.
        // To achieve a distinguishing observable, we instead use the public onlyOwner protection
        // difference effect: under original, non-owner cannot trigger transfer so c.balance stays same;
        // under mutant, anyone can trigger transfer and c.balance decreases. We simulate caller by
        // deploying the call through caller using calldata decode via abi.encodeWithSelector — but since
        // we cannot make the EVM treat msg.sender as arbitrary address in high-level test, we use
        // the low-level call and require that `caller == address(this)` for meaningful test.  
        // To keep the test machine-checkable and general, require that the actor here is the owner of C
        // or not via a param; we express property as: when msg.sender != owner, c.balance does not decrease.

        // ensure the test caller (this contract) is not the owner; require the owner is different
        address owner = c.owner();
        require(owner != address(this), "test contract is owner; choose different deployment");

        // Now call sendMoney from this contract (which is a non-owner). On original P this will revert due to onlyOwner
        // and thus c.balance remains the same. On mutant M it will succeed and reduce c.balance by `amount`.
        // Perform the call and capture success boolean (revert boolean observable)
        (bool ok, ) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("sendMoney(address,uint256)")), target, amount));

        uint after = address(c).balance;

        // The distinguishing property: when the caller is not the owner, C's balance must remain unchanged after the attempt.
        assert(after == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller is the test contract; ensure it's not the owner by requiring c.owner() != address(this)
    function run(address target, uint value) public payable {
        require(c.owner() != address(this));
        // attempt to call sendMoney as a non-owner
        bool reverted;
        try c.sendMoney(target, value) { reverted = false; } catch { reverted = true; }
        // On the original contract, non-owners' sendMoney calls must revert
        assert(reverted == true);
    }
    receive() external payable {}
}
